local _, ns = ...
if ns.LOCALE ~= "esES" and ns.LOCALE ~= "esMX" then return end
local L = ns.L

-- Options/Welcome.lua: What's New, by version (WN<id>_<n>), newest first; beside Locales/esES.lua.
L["WN14_1_TITLE"] = "Mando"
L["WN14_1_TEXT"] = "Con la interfaz de mando activa, el libro de hechizos clásico, los talentos y el registro de misiones se abren dentro de las ventanas del propio juego, para que un mando pueda moverse por ellos."
L["WN14_2_TITLE"] = "Tema en todo"
L["WN14_2_TEXT"] = "Con un tema activo, las piezas del propio juego también toman su color donde dejaste desactivadas las clásicas: minimapa, marcos de unidad, barras, ventanas y los botones del menú del juego."
L["WN14_3_TITLE"] = "Oscuridad"
L["WN14_3_TEXT"] = "Oscuro tiene un deslizador de gris claro a negro, con un botón para volver al valor predeterminado."
L["WN14_4_TITLE"] = "Color plano"
L["WN14_4_TEXT"] = "Color plano (Tema personalizado) muestra las partes que marques en un solo color plano, con las mismas formas."
L["WN14_5_TITLE"] = "Microbotones"
L["WN14_5_TEXT"] = "Ocultar microbotones ahora funciona en el micromenú del propio juego con la barra clásica desactivada, y puede ocultar la tienda."
L["WN14_6_TITLE"] = "Barras 6 a 8"
L["WN14_6_TEXT"] = "Ocultar barras 6 a 8 ya no existe: deciden los ajustes de barras de acción del propio juego."
L["WN14_7_TITLE"] = "Correcciones"
L["WN14_7_TEXT"] = "Coordenadas: ocultas y al pasar el ratón funcionan con el minimapa del juego, los botones de minimapa de otros accesorios toman el tema, y la mochila de un cazador muestra las casillas libres en lugar de la munición."
L["WN13_1_TITLE"] = "Brillo de amenaza"
L["WN13_1_TEXT"] = "Ocultar brillo de amenaza (Marcos de unidad) quita el brillo rojo de amenaza de los marcos de unidad. El número de amenaza del juego se mantiene."
L["WN13_2_TITLE"] = "Objetos de misión"
L["WN13_2_TEXT"] = "Objetos de misión sencillos (Ventanas de bolsa) muestra los objetos de misión de las bolsas y el banco sin el borde de misión."
L["WN13_3_TITLE"] = "Números"
L["WN13_3_TEXT"] = "Números sin separadores (Marcos de unidad) quita los separadores de miles de los números grandes, en las barras y en todo el juego."
L["WN13_4_TITLE"] = "Iconos de acción"
L["WN13_4_TEXT"] = "Con un tema activo, los iconos de acción vuelven a verse enteros, como en Classic Era; solo su propio borde toma el color del tema."
L["WN13_5_TITLE"] = "Tus barras"
L["WN13_5_TEXT"] = "Si la 0.14.0 cambió tus barras, una línea de chat al entrar te deja devolverlas a como estaban o elegir el aspecto clásico."
L["WN13_6_TITLE"] = "Ventana social"
L["WN13_6_TEXT"] = "Las pestañas Amigos y Banda van en su borde fino como en Classic Era, y la descripción de la pestaña Banda vuelve a verse fuera de una banda."
L["WN13_7_TITLE"] = "Correcciones"
L["WN13_7_TEXT"] = "El botín en el ratón se abre con el primer objeto bajo el cursor, las etiquetas de las pestañas se vuelven blancas al pasar el ratón, y Diseño clásico devuelve el micromenú y las casillas de bolsa clásicos."
L["WN12_1_TITLE"] = "Ventanas"
L["WN12_1_TEXT"] = "Junto al botón de cerrar de cada ventana hay un candado y un reinicio: desbloqueada, la ventana se arrastra por su título. Las ventanas de misión y de diálogo, la ventana social, el buscador de grupos y el libro de profesiones se colocan y se ajustan en Ventanas de ClassicUI Forever."
L["WN12_2_TITLE"] = "Temporizadores de golpe"
L["WN12_2_TEXT"] = "Los temporizadores de golpe del juego con el aspecto de la barra de lanzamiento 1.x, un color por mano y un destello en cada golpe. Los colores y el Grosor del borde se eligen en las opciones."
L["WN12_3_TITLE"] = "Barras de salud gruesas"
L["WN12_3_TEXT"] = "Una barra de salud más alta en los marcos de jugador, objetivo y foco, sobre el nombre o sobre el maná (Marcos de unidad). Recuadro de nombre con color de clase y Tamaño de nombres también son nuevos ahí."
L["WN12_4_TITLE"] = "Grifos"
L["WN12_4_TEXT"] = "Los grifos se arrastran, se ajustan o se ocultan en el modo de edición del juego. Con el ajuste activado se alinean con las barras y vuelven a su sitio."
L["WN12_5_TITLE"] = "Medidor de daño"
L["WN12_5_TEXT"] = "El medidor de daño en el marco 1.x, con botones clásicos y un fondo de mármol o de árbol de talentos que se puede mover."
L["WN12_6_TITLE"] = "Idiomas"
L["WN12_6_TEXT"] = "ClassicUI Forever ya está en alemán, francés, español e italiano."
L["WN12_7_TITLE"] = "Opciones"
L["WN12_7_TEXT"] = "Nuevas pestañas Preguntas y Apoyo, un Color personalizado para el tema y una búsqueda que encuentra un ajuste por más nombres."
L["WN12_8_TITLE"] = "Recursos"
L["WN12_8_TEXT"] = "La visualización personal de recursos en barras 1.x con el antiguo borde de placa de nombre, con el ajuste Separación de barras."
L["WN12_9_TITLE"] = "Barra clásica"
L["WN12_9_TEXT"] = "Casillas de bolsa de tamaño clásico, cualquier microbotón se puede ocultar, el botón de Ayuda vuelve al final del micromenú y La franja sostiene las barras 2 y 3 mantiene esas barras en la franja."
L["WN12_10_TITLE"] = "Minimapa y chat"
L["WN12_10_TEXT"] = "Coordenadas, y un borde y una cabecera que se pueden ocultar en el minimapa, el ojo del buscador de grupos en él cuando su microbotón está oculto, y cada botón del chat se oculta por separado."
L["WN12_11_TITLE"] = "Correcciones"
L["WN12_11_TEXT"] = "Las barras ya no saltan a lo alto de la pantalla tras arrastrarlas en el modo de edición, la barra 1 se mueve con las flechas en el modo de edición, la barra de experiencia ya no sale doble al entrar en combate y las páginas de botín ya no repiten objetos."
L["WN12_12_TITLE"] = "Correcciones menores"
L["WN12_12_TEXT"] = "Los números de mascota y de grupo caben en sus barras, el micromenú ya no salta al arrastrarlo, la barra de latencia conserva su marco y las ayudas de los microbotones salen una vez y con el límite de misiones correcto."
L["WN11_1_TITLE"] = "Chat"
L["WN11_1_TEXT"] = "Ocultar botones de chat permite que el chat quede en el borde de la pantalla, y Barra de desplazamiento del chat mantiene la de WoW Forever (Botones de chat)."
L["WN11_2_TITLE"] = "Niveles de misión"
L["WN11_2_TEXT"] = "Niveles de misión (Misiones) muestra el nivel de cada misión en el mapa, en el seguimiento y en el registro de misiones, en sintonía con el filtro propio del mapa."
L["WN11_3_TITLE"] = "Tema oscuro"
L["WN11_3_TEXT"] = "Los menús de clic derecho, los botones de minimapa de accesorios, los botones de zoom, el reloj y el icono de día y noche toman el tema, y los iconos de acción no muestran borde claro."
L["WN11_4_TITLE"] = "Correcciones"
L["WN11_4_TEXT"] = "Sin nivel de misión duplicado en el seguimiento, sin errores de los menús de clic derecho en mazmorras, y el menú del objetivo se queda en pantalla."
L["WN10_1_TITLE"] = "Minimapa"
L["WN10_1_TEXT"] = "Cada parte del minimapa puede mostrarse, mostrarse solo al pasar el ratón u ocultarse (Minimapa en las opciones), y acercar y alejar se mueven cada uno por el anillo en Ventanas de ClassicUI Forever."
L["WN10_2_TITLE"] = "Micromenú"
L["WN10_2_TEXT"] = "Las descripciones de Classic Era en las descripciones de los microbotones, y Ocultar microbotones quita botones sueltos del menú (Barra clásica)."
L["WN10_3_TITLE"] = "Llavero"
L["WN10_3_TEXT"] = "Se abre aunque no tenga llaves, en su propia ventana, con el arte de Classic Era."
L["WN10_4_TITLE"] = "Nuevas opciones"
L["WN10_4_TEXT"] = "Ocultar barra de actitud (Barra clásica), Tamaño del texto del nombre (Placas de nombre) y Descripción de unidad en las barras (Marcos de unidad)."
L["WN10_5_TITLE"] = "Correcciones"
L["WN10_5_TEXT"] = "Las flechas de desplazamiento se vuelven grises cuando no hay nada que desplazar, el registro de misiones resalta como en Classic Era, Última conexión de la hermandad ordena bien y la ventana de macros se abre junto al libro de hechizos."
L["WN10_6_TITLE"] = "Correcciones menores"
L["WN10_6_TEXT"] = "Las flechas de talentos, la pestaña de hermandad sin hermandad, las flechas de página sobre el mapa, la bolsa de botones de accesorios y avisos de diseño más cortos."
L["WN9_1_TITLE"] = "Mapa del mundo clásico"
L["WN9_1_TEXT"] = "El mapa pequeño de Classic Era, con la lista de misiones del mapa en su propio panel al lado y las recompensas tras el texto de la misión. Barra de navegación del mapa en Mapa de las opciones devuelve el diseño de mapa del juego."
L["WN9_2_TITLE"] = "Nuevas opciones"
L["WN9_2_TEXT"] = "Ocultar botón de misiones del mapa (Mapa), Barras de tamaño clásico (Barra clásica) y Sacudida al interrumpir (Barras de lanzamiento)."
L["WN9_3_TITLE"] = "Estilo clásico"
L["WN9_3_TEXT"] = "Los menús de clic derecho, los desplegables, la ventana social, el buscador de grupos, la lista Quién y la lista de la hermandad siguen a Classic Era; la ventana de opciones toma el aspecto del cliente actual de Classic Era, y la lista de ignorados y el probador el estilo clásico."
L["WN9_4_TITLE"] = "Modo edición"
L["WN9_4_TEXT"] = "El libro de hechizos se puede mover y redimensionar en Ventanas de ClassicUI Forever."
L["WN9_5_TITLE"] = "Barras y seguimiento"
L["WN9_5_TEXT"] = "Las barras 4 y 5 mantienen su sitio en el borde de la pantalla, y el seguimiento de misiones ya no se pone encima de ellas."
L["WN9_6_TITLE"] = "Correcciones"
L["WN9_6_TEXT"] = "Los PNJ neutrales muestran su nivel en lugar de una calavera, y hacer clic en las barras de un marco de unidad vuelve a seleccionar objetivo."
L["WN9_7_TITLE"] = "Ventanas y pestañas"
L["WN9_7_TEXT"] = "Las ventanas de vendedor, correo, cédula de hermandad y tabardo, y muchas otras ventanas y pestañas, se alinean con Classic Era; Escape cierra la ventana de cédula de hermandad."
L["WN8_1_TITLE"] = "Grifos sobre las barras"
L["WN8_1_TEXT"] = "Marca Grifos sobre las barras en Barra clásica de las opciones para dibujar los grifos delante de las barras 2 y 3."
L["WN8_2_TITLE"] = "Ventanas que abren al pulsar"
L["WN8_2_TEXT"] = "Las teclas del libro de hechizos, profesiones, talentos, hermandad y registro de misiones y Escape actúan al pulsar, como las ventanas propias del juego."
L["WN8_3_TITLE"] = "Correcciones"
L["WN8_3_TEXT"] = "Los hechizos se vuelven a arrastrar a la barra de acción 1, el nombre de zona se centra en la barra del minimapa esté donde esté el calendario, y las pestañas y órdenes de mascota del libro de hechizos se ven bien."
L["WN7_1_TITLE"] = "Texto de teclas clásico"
L["WN7_1_TEXT"] = "Los nombres de teclas en los botones de acción tienen el tamaño y el contorno de Classic Era. Tamaño del texto de teclas en Estilo de botones de las opciones los agranda o los reduce."
L["WN7_2_TITLE"] = "Sitios del calendario"
L["WN7_2_TEXT"] = "El calendario es un pequeño cuadrado junto al nombre de zona; ponlo en el anillo o detrás del icono de día y noche en Botón del calendario de las opciones. Marca Calendario en Minimapa de Ventanas de ClassicUI Forever en el modo edición para moverlo o redimensionarlo."
L["WN6_1_TITLE"] = "Botón del calendario"
L["WN6_1_TEXT"] = "El calendario está bajo el icono de día y noche del minimapa. Para ocultarlo, desmarca Botón del calendario en Minimapa de las opciones."
L["WN5_1_TITLE"] = "Correcciones"
L["WN5_1_TEXT"] = "La marca de jugadores nuevos bienvenidos del buscador de grupos se alinea con los iconos de rol. Detalles en el registro de cambios completo."
L["WN4_1_TITLE"] = "Correcciones"
L["WN4_1_TEXT"] = "Las pestañas toman el ratón en la propia pestaña, una profesión lanzada desde el libro de hechizos cierra el libro en combate, y la cabecera de la ventana de botín queda limpia. Detalles en el registro de cambios completo."
L["WN3_1_TITLE"] = "Piezas de la barra clásica"
L["WN3_1_TEXT"] = "Classic no tenía botón de profesiones ni bolsa de componentes, así que el botón de profesiones sale del micromenú (las profesiones se abren desde el libro de hechizos) y la bolsa de componentes es un pequeño botón redondo al pasar el ratón. Las barras 2 y 3 vuelven a caber entre los grifos. Ambas son filas en Barra clásica de las opciones."
L["WN2_1_TITLE"] = "Modo edición de ventanas"
L["WN2_1_TEXT"] = "Marca Ventanas en el modo edición para mover y redimensionar la ficha de personaje, el libro de hechizos, los talentos, el registro de misiones, las profesiones y el mapa."
L["WN2_2_TITLE"] = "Perfiles"
L["WN2_2_TEXT"] = "Una pestaña Perfiles en las opciones guarda ajustes con nombre por personaje."
L["WN2_3_TITLE"] = "Bronce u Oscuro"
L["WN2_3_TEXT"] = "El tema personalizado viene en el bronce de Forever o en un antracita oscuro. Mira la opción Tema personalizado."
L["WN2_4_TITLE"] = "Barra clásica"
L["WN2_4_TEXT"] = "Las barras ya no se reducen por defecto. La barra lleva ahora la barra de latencia, el llavero y la bolsa de componentes como en clásico; cada uno se puede mover en el modo edición u ocultar en Barra clásica de las opciones."
L["WN2_5_TITLE"] = "Botones del minimapa"
L["WN2_5_TEXT"] = "Los botones de minimapa de otros accesorios pueden agruparse tras un botón en el anillo. Mira la opción Agrupar botones de accesorios."
L["WN2_6_TITLE"] = "Opciones"
L["WN2_6_TEXT"] = "Secciones de Misiones y Mapa, y filas nuevas para el marco del mapa, la ventana de botín, las tiradas de botín, ocultar el seguimiento del juego, el botón de profesiones y el texto de teclas."
L["WN2_7_TITLE"] = "Restablecer diseño clásico"
L["WN2_7_TEXT"] = "Devuelve de una vez las ventanas, el seguimiento, los grifos, las piezas de barra y los ajustes de diseño."
